/* Unit tests for js/core.js  —  node tests/test_core.js */
const assert=require('assert');const F=require('../js/core.js');const {startAny}=require('./start_any.js');   /* startAny = test-only start for fewer than 8 managers; the shipped F.mStart needs exactly 8 */
let pass=0,fail=0;const pend=[];
function t(name,fn){pend.push([name,fn])}
async function run(){for(const [n,fn] of pend){try{await fn();pass++;console.log('  ok  '+n)}catch(e){fail++;console.log('FAIL  '+n+'\n      '+(e&&e.message||e))}}
  console.log('\n'+pass+' passed, '+fail+' failed');process.exit(fail?1:0)}
const NOW=Date.UTC(2026,9,28,5,0,0);
const base=()=>({name:'Test League',mgrName:'Ana',teamName:'Aces',managers:8,rounds:8,type:'snake',startAt:null,startMode:'manual',orderMode:'random',clockSecs:60,autoPick:true,pass:'abcd'});
const fakeStore=(lat)=>{const kv={};const io={kv,reads:0,writes:0,read:async k=>{io.reads++;await new Promise(r=>setTimeout(r,lat||0));return kv[k]==null?'':kv[k]},write:async(k,o)=>{io.writes++;await new Promise(r=>setTimeout(r,lat||0));kv[k]=typeof o==='string'?o:JSON.stringify(o)},sleep:ms=>new Promise(r=>setTimeout(r,Math.min(ms,5)))};return io};
const POOL=Array.from({length:162},(_,i)=>String(1000+i));

/* ---------- settings + wizard validation ---------- */
t('defaults match the spec (60 s clock, 8 rounds, snake, random, auto-pick on)',()=>{const d=F.DEFAULTS;assert.equal(d.clockSecs,60);assert.equal(d.rounds,8);assert.equal(d.type,'snake');assert.equal(d.orderMode,'random');assert.equal(d.autoPick,true);assert.deepEqual(F.CLOCKS,[30,60,90,120,180,0])});
t('valid settings pass',()=>assert.ok(F.validateSettings(base(),{needPass:true,poolSize:162,now:NOW}).ok));
t('every NEW league has exactly 8 managers (anything else is refused; a stored legacy count is only accepted when the caller says so)',()=>{for(const n of [2,3,4,6,7,9,12,13,0,-1,4.5,'8',null,undefined])assert.ok(F.validateSettings(Object.assign(base(),{managers:n}),{now:NOW}).errors.managers,String(n));assert.ok(!F.validateSettings(Object.assign(base(),{managers:8}),{now:NOW}).errors.managers);assert.equal(F.MANAGERS,8);assert.equal(F.DEFAULTS.managers,8);assert.ok(/exactly 8/.test(F.validateSettings(Object.assign(base(),{managers:6}),{now:NOW}).errors.managers));
  assert.ok(!F.validateSettings(Object.assign(base(),{managers:6}),{now:NOW,legacyCount:6}).errors.managers);assert.ok(F.validateSettings(Object.assign(base(),{managers:7}),{now:NOW,legacyCount:6}).errors.managers)});
t('league name length and cleaning',()=>{assert.ok(F.validateSettings(Object.assign(base(),{name:' a '}),{now:NOW}).errors.name);assert.ok(F.validateSettings(Object.assign(base(),{name:'x'.repeat(41)}),{now:NOW}).errors.name);assert.ok(!F.validateSettings(Object.assign(base(),{name:'<b>Hi</b>'}),{now:NOW}).errors.name);assert.equal(F.clean('a<b>\n  c'),'a c');assert.equal(F.clean('<img src=x onerror=alert(1)>'),'');assert.equal(F.clean('Ann <b>m</b> Lee'),'Ann m Lee')});
t('rounds bounded and limited by the pool size',()=>{assert.ok(F.validateSettings(Object.assign(base(),{rounds:0}),{now:NOW}).errors.rounds);assert.ok(F.validateSettings(Object.assign(base(),{rounds:16}),{now:NOW}).errors.rounds);
  const e=F.validateSettings(Object.assign(base(),{managers:8,rounds:15}),{poolSize:100,now:NOW}).errors.rounds;assert.ok(/Not enough teams/.test(e));assert.equal(F.maxRounds(8,162),15);assert.equal(F.maxRounds(8,100),12);assert.equal(F.maxRounds(8,162),Math.min(F.LIMITS.roundsMax,Math.floor(162/8)));assert.equal(F.maxRounds(12,162),13)});
t('clock presets only',()=>{for(const c of [30,60,90,120,180,0])assert.ok(!F.validateSettings(Object.assign(base(),{clockSecs:c}),{now:NOW}).errors.clockSecs);for(const c of [45,-1,null,'60'])assert.ok(F.validateSettings(Object.assign(base(),{clockSecs:c}),{now:NOW}).errors.clockSecs)});
t('draft time must be in the future; auto-start needs a time',()=>{assert.ok(F.validateSettings(Object.assign(base(),{startAt:NOW-1000}),{now:NOW}).errors.startAt);assert.ok(F.validateSettings(Object.assign(base(),{startAt:NOW+30000}),{now:NOW}).errors.startAt);assert.ok(!F.validateSettings(Object.assign(base(),{startAt:NOW+3600e3}),{now:NOW}).errors.startAt);
  assert.ok(F.validateSettings(Object.assign(base(),{startMode:'auto'}),{now:NOW}).errors.startMode);assert.ok(!F.validateSettings(Object.assign(base(),{startMode:'auto',startAt:NOW+3600e3}),{now:NOW}).errors.startMode)});
t('type, order mode and auto-pick must be valid values',()=>{const e=F.validateSettings(Object.assign(base(),{type:'x',orderMode:'y',autoPick:'yes'}),{now:NOW}).errors;assert.ok(e.type&&e.orderMode&&e.autoPick)});
t('no passcode in the wizard: settings carry no pass field, validation ignores it',()=>{const e=F.validateSettings(Object.assign(base(),{pass:'a'}),{now:NOW}).errors;assert.ok(!e.pass);assert.ok(!F.stepsFor({startAt:null}).includes('pass'))});
t('commissioner name and team are required when asked',()=>{const e=F.validateSettings(Object.assign(base(),{mgrName:'',teamName:' '}),{now:NOW}).errors;assert.ok(e.mgrName&&e.teamName)});
t('wizard: steps in order, "start" screen only when a time is set',()=>{assert.deepEqual(F.WIZARD[0],'you');assert.equal(F.WIZARD[F.WIZARD.length-1],'confirm');assert.ok(!F.stepsFor({startAt:null}).includes('start'));assert.ok(F.stepsFor({startAt:NOW}).includes('start'));assert.equal(F.stepsFor({startAt:null}).length,F.WIZARD.length-1);assert.ok(!F.WIZARD.includes('managers'),'no managers step');assert.equal(F.WIZARD.length,9)});
t('wizard: each step validates only its own fields',()=>{const s=Object.assign(base(),{name:'',managers:2});/* managers is not a wizard field any more; the confirm screen still refuses a wrong count */
  assert.ok(!F.validateStep('you',s,{now:NOW}).ok);assert.deepEqual(Object.keys(F.validateStep('you',s,{now:NOW}).errors),['name']);
  assert.ok(F.validateStep('type',s,{now:NOW}).ok);assert.ok(F.validateStep('clock',s,{now:NOW}).ok);
  const c=F.validateStep('confirm',s,{now:NOW,poolSize:162});assert.ok(!c.ok);assert.ok(c.errors.name&&c.errors.managers)});
t('wizard: a good set of answers passes every step and the confirm screen',()=>{const s=base();F.WIZARD.forEach(k=>assert.ok(F.validateStep(k,s,{now:NOW,poolSize:162}).ok,k))});
t('wizard: rounds step catches pool overflow',()=>{const r=F.validateStep('rounds',Object.assign(base(),{managers:8,rounds:14}),{now:NOW,poolSize:100});assert.ok(!r.ok&&r.errors.rounds)});
t('normalizeSettings fills defaults and drops bad values',()=>{const n=F.normalizeSettings({managers:'6',rounds:'x',type:'weird',clockSecs:45,startMode:'auto',startAt:null});assert.equal(n.managers,6);assert.equal(n.rounds,8);assert.equal(n.type,'snake');assert.equal(n.clockSecs,60);assert.equal(n.startMode,'manual');assert.equal(F.normalizeSettings({type:'linear'}).type,'linear')});

/* ---------- ids / keys ---------- */
t('league id: 16 chars Crockford, unique, code round-trips',()=>{const ids=new Set();for(let i=0;i<500;i++){const id=F.makeLeagueId();assert.equal(id.length,16);assert.ok(/^[0-9A-HJKMNP-TV-Z]+$/.test(id));ids.add(id);assert.equal(F.parseCode(F.formatCode(id)),id)}assert.equal(ids.size,500);assert.equal(F.parseCode('nope'),null);assert.equal(F.parseCode(F.formatCode('0123456789ABCDEF').replace('0','O')),'0123456789ABCDEF')});
t('keys are namespaced by the league id and kept short',()=>{const K=F.Keys('ABCDEFGHJKMNPQRS');assert.ok(K.meta.startsWith('fbn1-abcdefghjkmnpqrs-'));assert.notEqual(K.slot(1,0),K.slot(1,1));assert.notEqual(K.pick(1,5),K.pick(2,5));assert.ok(K.pick(12,200).length<64);const all=[K.meta,K.chat,K.slot(3,0),K.mgr('aabbccdd'),K.pick(1,1),K.pref('aabbccdd'),K.pres('aabbccdd'),K.spin(1,1,1)];assert.equal(new Set(all).size,all.length);all.forEach(k=>assert.ok(!/stoopid/i.test(k)))});

/* ---------- snake / linear derivation + custom order ---------- */
t('snake order is a-b-c / c-b-a / a-b-c',()=>{const o=['a','b','c'];assert.equal(F.pickSeq(o,3,'snake').map(s=>s.owner).join(''),'abccbaabc')});
t('linear order repeats a-b-c every round',()=>{const o=['a','b','c'];assert.equal(F.pickSeq(o,3,'linear').map(s=>s.owner).join(''),'abcabcabc')});
t('every manager gets exactly `rounds` picks in both types, for N=4..12',()=>{for(const type of ['snake','linear'])for(let N=4;N<=12;N++){const o=Array.from({length:N},(_,i)=>'m'+i);const seq=F.pickSeq(o,8,type);assert.equal(seq.length,N*8);o.forEach(m=>assert.equal(seq.filter(s=>s.owner===m).length,8));assert.equal(seq[seq.length-1].n,N*8)}});
t('snake: last of a round also picks first of the next; linear does not',()=>{const o=['a','b','c','d'];const s=F.pickSeq(o,2,'snake');assert.equal(s[3].owner,'d');assert.equal(s[4].owner,'d');const l=F.pickSeq(o,2,'linear');assert.equal(l[3].owner,'d');assert.equal(l[4].owner,'a')});
t('slotAt bounds and rounds',()=>{const o=['a','b'];assert.equal(F.slotAt(o,0,'snake',2),null);assert.equal(F.slotAt(o,5,'snake',2),null);assert.equal(F.slotAt(o,3,'snake',2).round,2);assert.equal(F.slotAt([],1,'snake',2),null)});
t('boardGrid matches slotAt',()=>{for(const type of ['snake','linear']){const o=['a','b','c','d','e'];const g=F.boardGrid(5,4,type);g.forEach((row,r)=>row.forEach((n,c)=>{const s=F.slotAt(o,n,type,4);assert.equal(s.col,c);assert.equal(s.round,r+1)}))}});
t('custom order: moveItem/moveTo keep it a permutation; edges refuse',()=>{const a=['a','b','c','d'];assert.deepEqual(F.moveItem(a,'b',-1),['b','a','c','d']);assert.equal(F.moveItem(a,'a',-1),null);assert.equal(F.moveItem(a,'d',1),null);assert.deepEqual(F.moveTo(a,'d',0),['d','a','b','c']);assert.deepEqual(F.moveTo(a,'a',3),['b','c','d','a']);assert.equal(F.moveTo(a,'zz',1),null);assert.equal(F.moveTo(a,'a',9),null)});
const lobbyMeta=(over)=>{const m=F.defaultMeta('ID',Object.assign({name:'Test League',managers:6,rounds:8},over||{}),'m0');return m};
const J=n=>Array.from({length:n},(_,i)=>'m'+i);
t('custom order: mSetOrder accepts permutations only and only in the lobby',()=>{const m=lobbyMeta();const j=J(4);const r=F.mSetOrder(m,j,['m3','m1','m0','m2']);assert.deepEqual(r.state.order,['m3','m1','m0','m2']);assert.ok(r.state.orderSet);assert.ok(F.mSetOrder(m,j,['m3','m1','m0']).error);assert.ok(F.mSetOrder(m,j,['m3','m1','m0','zz']).error);assert.ok(F.mSetOrder(m,j,['m0','m0','m1','m2']).error);const live=Object.assign({},m,{status:'live'});assert.ok(/locked/i.test(F.mSetOrder(live,j,j).error))});
t('custom order: effectiveOrder keeps the saved order and appends late joiners; drops leavers',()=>{const m=F.mSetOrder(lobbyMeta(),J(3),['m2','m0','m1']).state;assert.deepEqual(F.effectiveOrder(m,J(3)),['m2','m0','m1']);assert.deepEqual(F.effectiveOrder(m,['m0','m1','m2','m3']),['m2','m0','m1','m3']);assert.deepEqual(F.effectiveOrder(m,['m0','m2']),['m2','m0']);assert.deepEqual(F.effectiveOrder(lobbyMeta(),['m1','m0']),['m1','m0'])});
t('custom order: mMove up/down and the lock on start',()=>{let m=lobbyMeta();m=F.mMove(m,J(4),'m3',-1).state;assert.deepEqual(m.order,['m0','m1','m3','m2']);m=F.mMove(m,J(4),'m3',-1).state;m=F.mMove(m,J(4),'m3',-1).state;assert.deepEqual(m.order,['m3','m0','m1','m2']);assert.ok(F.mMove(m,J(4),'m3',-1).error);
  const st=startAny(m,J(4),NOW,'x',162).state;assert.ok(F.mMove(st,J(4),'m0',1).error);assert.ok(F.mRandomize(st,J(4)).error);assert.ok(F.mSetOrder(st,J(4),J(4)).error)});
t('"I set the order" start keeps exactly the commissioner order (no shuffle)',()=>{let m=lobbyMeta({orderMode:'manual'});m=F.mSetOrder(m,J(5),['m4','m3','m2','m1','m0']).state;const s=startAny(m,J(5),NOW,'seed',162).state;assert.deepEqual(s.order,['m4','m3','m2','m1','m0'])});
t('manual mode without any edit uses join order',()=>{const m=lobbyMeta({orderMode:'manual'});assert.deepEqual(startAny(m,J(5),NOW,'seed',162).state.order,J(5))});
t('random start shuffles deterministically per seed, and is a permutation',()=>{const m=lobbyMeta({managers:8});const a=F.mStart(m,J(8),NOW,'s1',162).state.order,b=F.mStart(m,J(8),NOW,'s1',162).state.order,c=F.mStart(m,J(8),NOW,'s2',162).state.order;assert.deepEqual(a,b);assert.ok(F.permutationOf(a,J(8)));assert.notDeepEqual(a,c);let moved=0;for(let i=0;i<20;i++)if(F.mStart(m,J(8),NOW,'k'+i,162).state.order.join()!==J(8).join())moved++;assert.ok(moved>=18)});
t('a Randomize in the lobby counts as setting the order (start then keeps it)',()=>{const m=F.mRandomize(lobbyMeta(),J(6),F.mulberry(7)).state;assert.ok(m.orderSet&&F.permutationOf(m.order,J(6)));assert.deepEqual(startAny(m,J(6),NOW,'z',162).state.order,m.order)});
t('start needs EXACTLY 8 managers: 0-7 (and 9+) are refused with a plain message, 8 starts; already started and not enough teams are still refused',()=>{
  for(const n of [0,1,2,3,4,5,6,7,9,12]){const r=F.mStart(lobbyMeta({managers:8}),J(n),NOW,'s',162);assert.ok(r.error&&!r.state,n+' managers must not start');assert.ok(/8 managers/.test(r.error),r.error)}
  assert.ok(/Waiting for 3 more managers/.test(F.mStart(lobbyMeta(),J(5),NOW,'s',162).error));assert.ok(/Waiting for 1 more manager\./.test(F.mStart(lobbyMeta(),J(7),NOW,'s',162).error));
  const s=F.mStart(lobbyMeta({managers:8}),J(8),NOW,'s',162).state;assert.equal(s.status,'live');assert.equal(s.order.length,8);assert.ok(F.mStart(s,J(8),NOW,'s',162).error);
  assert.ok(F.mStart(lobbyMeta({rounds:15,managers:8}),J(8),NOW,'s',100).error);
  /* the test-only helper must agree with the shipped function for 8 managers (so tests that use it exercise the same start) */
  const m8=lobbyMeta({managers:8,orderMode:'manual'});assert.deepEqual(startAny(m8,J(8),NOW,'s',162).state,F.mStart(m8,J(8),NOW,'s',162).state);
  const mr=lobbyMeta({managers:8});assert.deepEqual(startAny(mr,J(8),NOW,'q',162).state,F.mStart(mr,J(8),NOW,'q',162).state)});
t('the shipped room has no start path for fewer than 8 managers (no "start anyway", no 2-manager minimum, no test mode)',()=>{const fs=require('fs'),path=require('path');const root=path.join(__dirname,'..');const rj=fs.readFileSync(path.join(root,'js/room.js'),'utf8'),cj=fs.readFileSync(path.join(root,'js/core.js'),'utf8');
  assert.ok(!/start anyway|You can start with fewer|At least 2 managers|MG\.length<2\)return;|j<2\)/i.test(rj),'room.js still has a short start path');assert.ok(!/joined\.length<2/.test(cj),'core.js start minimum of 2');
  assert.ok(!/startAny|testMode|test_mode|bypass/i.test(rj+cj),'no test bypass in shipped code');assert.ok(/F\.MANAGERS/.test(rj))});
t('settings edit: only in the lobby; validates; the manager count cannot be changed',()=>{const m=lobbyMeta({managers:8});const cl=n=>Array.from({length:n},(_,i)=>({mid:'m'+i,i:i+1}));
  const ok=F.mSettings(m,{type:'linear',rounds:6,clockSecs:90},cl(3),162,NOW);assert.equal(ok.state.settings.type,'linear');assert.equal(ok.state.settings.rounds,6);assert.equal(ok.state.settings.clockSecs,90);
  /* the number of managers cannot be changed any more: a patch carrying it is ignored */assert.equal(F.mSettings(m,{managers:5,rounds:7},cl(6),162,NOW).state.settings.managers,8);assert.equal(F.mSettings(m,{managers:12},cl(2),162,NOW).state.settings.managers,8);assert.ok(F.mSettings(m,{clockSecs:45},cl(2),162,NOW).error);
  assert.ok(F.mSettings(Object.assign({},m,{status:'live'}),{type:'linear'},cl(2),162,NOW).error);const t1=F.mSettings(m,{startAt:NOW+7200e3,startMode:'auto'},cl(2),162,NOW);assert.equal(t1.state.settings.startMode,'auto');assert.ok(F.mSettings(m,{startAt:NOW-5e3},cl(2),162,NOW).error)});

/* ---------- time zones ---------- */
t('tz offsets incl. half-hour zones and DST',()=>{const w=Date.UTC(2026,0,15,12);const s=Date.UTC(2026,6,15,12);assert.equal(F.tzOffsetMin(w,'America/New_York'),-300);assert.equal(F.tzOffsetMin(s,'America/New_York'),-240);assert.equal(F.tzOffsetMin(w,'Asia/Jakarta'),420);assert.equal(F.tzOffsetMin(w,'Asia/Kolkata'),330);assert.equal(F.tzOffsetMin(w,'UTC'),0);assert.equal(F.tzOffsetMin(w,'Australia/Sydney'),660)});
t('zonedToUtc: Sat 8:00 PM in different zones',()=>{assert.equal(F.zonedToUtc(2026,10,31,20,0,'Asia/Jakarta'),Date.UTC(2026,9,31,13,0));assert.equal(F.zonedToUtc(2026,10,31,20,0,'America/New_York'),Date.UTC(2026,10,1,0,0));assert.equal(F.zonedToUtc(2026,11,7,20,0,'America/New_York'),Date.UTC(2026,10,8,1,0));assert.equal(F.zonedToUtc(2026,10,31,20,0,'UTC'),Date.UTC(2026,9,31,20,0))});
t('parseLocalInput / localInputValue round-trip in many zones',()=>{for(const z of ['Asia/Jakarta','America/Los_Angeles','Europe/London','Asia/Kolkata','Pacific/Auckland','UTC'])for(const s of ['2026-11-07T20:00','2027-03-14T09:30','2027-07-01T00:05']){const ms=F.parseLocalInput(s,z);assert.ok(isFinite(ms));assert.equal(F.localInputValue(ms,z),s,z+' '+s)}assert.equal(F.parseLocalInput('garbage','UTC'),null);assert.equal(F.parseLocalInput('','UTC'),null)});
t('time-zone display: the same instant reads in each viewer\'s own zone',()=>{const ms=F.zonedToUtc(2026,11,7,20,0,'America/New_York');   /* commissioner: Sat Nov 7, 8:00 PM New York */
  const ny=F.startsLine(ms,'America/New_York','America/New_York'),jk=F.startsLine(ms,'Asia/Jakarta','America/New_York'),ld=F.startsLine(ms,'Europe/London','America/New_York'),la=F.startsLine(ms,'America/Los_Angeles','America/New_York');
  assert.ok(/^Starts Sat, November 7, 2026(?: at |, )8:00 PM your time \(EST · UTC-5\)$/.test(ny.you),ny.you);assert.ok(/^Starts Sun, November 8, 2026(?: at |, )8:00 AM your time \(GMT\+7\)$/.test(jk.you),jk.you);assert.ok(/Sun, November 8, 2026(?: at |, )1:00 AM your time \(GMT\)/.test(ld.you),ld.you);assert.ok(/Sat, November 7, 2026(?: at |, )5:00 PM your time \(PST · UTC-8\)/.test(la.you),la.you);
  assert.ok(/New York/.test(jk.commish)&&/8:00 PM/.test(jk.commish),jk.commish);assert.ok(/Commissioner’s zone: New York/.test(ny.commish));assert.equal(jk.utc,'Sun, 08 Nov 2026, 01:00 UTC')});
t('avatar initial: first letter or digit, else the whole first emoji, never half a surrogate pair (QA L1)',()=>{assert.equal(F.initialOf('ana'),'A');assert.equal(F.initialOf('🏀 Ana'),'A');assert.equal(F.initialOf('🏀'),'🏀');assert.equal(F.initialOf('7th Man'),'7');assert.equal(F.initialOf('élan'),'É');assert.equal(F.initialOf(''),'?');assert.equal(F.initialOf(null),'?');assert.ok(!/[\ud800-\udbff](?![\udc00-\udfff])/.test(F.avatarSpec({name:'🏀'}).text));assert.equal(F.avatarSpec({name:'🏀 Zed'}).text,'Z')});
t('startsLine carries the year (Month Day, Year) in the viewer and commissioner lines (QA L2)',()=>{const l=F.startsLine(Date.UTC(2026,9,31,13,0),'Asia/Jakarta','America/New_York');assert.ok(/October 31, 2026/.test(l.you),l.you);assert.ok(/October 31, 2026/.test(l.commish),l.commish)});
t('reissueSeat: new secret, same seat; the old secret stops verifying and the new one verifies',async()=>{const k0=F.newSecret(),mid='a1b2c3d4e5f6';const c0=F.makeClaim({mid,i:3,gen:1,name:'Ana',team:'Hoops',sh:await F.mgrHash(mid,k0),w:'x'});assert.ok(await F.checkMgrSecret(c0,k0));
  const r=await F.reissueSeat(c0);assert.notEqual(r.k,k0);assert.equal(r.claim.mid,mid);assert.equal(r.claim.i,3);assert.equal(r.claim.gen,1);assert.equal(r.claim.name,'Ana');assert.equal(r.claim.w,'x');assert.ok(await F.checkMgrSecret(r.claim,r.k),'new secret verifies');assert.ok(!(await F.checkMgrSecret(r.claim,k0)),'old secret no longer verifies');assert.ok(F.parseClaim(JSON.stringify(r.claim)),'still a valid claim record')});
t('startsLine with no commissioner zone, and same-offset zones do not repeat',()=>{const ms=Date.UTC(2026,9,31,13,0);assert.equal(F.startsLine(ms,'Asia/Jakarta').commish,'');assert.ok(/Commissioner’s zone/.test(F.startsLine(ms,'Asia/Jakarta','Asia/Bangkok').commish))});
t('countdown text',()=>{assert.equal(F.countdownText(90061e3),'1d 1h');assert.equal(F.countdownText(3720e3),'1h 02m');assert.equal(F.countdownText(125e3),'2m 05s');assert.equal(F.countdownText(9e3),'9s');assert.equal(F.countdownText(-5),'0s')});
t('reminder message: league, UTC time, local-time link, invite link; no money words',()=>{const o={name:'Hoops Club',startAt:Date.UTC(2026,10,7,1,0),timeLink:'https://x/time.html?t=1',inviteLink:'https://x/join.html?l=ABC',rounds:8,type:'snake',clockSecs:60};const r=F.reminderText(o);assert.ok(r.includes('Hoops Club')&&r.includes('UTC')&&r.includes(o.timeLink)&&r.includes(o.inviteLink)&&/60 seconds/.test(r)&&/snake/.test(r));assert.ok(!/bet|stake|\$|prize|payout|fee|owe|iou/i.test(r),r);const n=F.reminderText(Object.assign({},o,{startAt:null,clockSecs:0,type:'linear'}));assert.ok(/to be announced/.test(n)&&/no pick clock/.test(n)&&/linear/.test(n))});

/* ---------- photos ---------- */
const mkUrl=b=>'data:image/jpeg;base64,'+Buffer.alloc(b,7).toString('base64');
t('photoBytes measures base64 payload; rejects other data',()=>{assert.equal(F.photoBytes(mkUrl(1000)),1000);assert.equal(F.photoBytes(mkUrl(1001)),1001);assert.equal(F.photoBytes('http://x/a.png'),-1);assert.equal(F.photoBytes('data:text/html;base64,AAAA'),-1);assert.equal(F.photoBytes(''),-1);assert.equal(F.photoBytes(null),-1)});
t('fitPhoto lands under the 25 KB cap, shrinking quality then size',async()=>{const calls=[];const r=await F.fitPhoto(async(e,q)=>{calls.push([e,q]);return mkUrl(Math.round(e*e*q*0.75))});assert.ok(r&&r.bytes<=25*1024);assert.ok(calls.length>1);assert.equal(calls[0][0],256);const small=await F.fitPhoto(async()=>mkUrl(500));assert.equal(small.tries,1);assert.equal(small.edge,256)});
t('fitPhoto gives up (null) when nothing fits',async()=>{assert.equal(await F.fitPhoto(async()=>mkUrl(60000)),null)});
t('photo cap: profiles drop oversized or fake photos; avatars fall back to emoji/initial',()=>{assert.equal(F.makeProfile({mid:'aa',name:'A',team:'T',photo:mkUrl(50*1024)}).photo,'');assert.ok(F.makeProfile({mid:'aa',name:'A',team:'T',photo:mkUrl(20*1024)}).photo);assert.equal(F.parseProfile(JSON.stringify({mid:'aa',name:'A',team:'T',photo:'javascript:alert(1)'})).photo,'');
  assert.equal(F.avatarSpec({name:'zed',emoji:'🔥'}).kind,'emoji');assert.equal(F.avatarSpec({name:'zed'}).text,'Z');assert.equal(F.avatarSpec({name:'zed',photo:mkUrl(900)}).kind,'photo');assert.equal(F.avatarSpec({name:'zed',photo:mkUrl(90*1024)}).kind,'initial')});
t('cropRect stays inside the image',()=>{for(const [w,h] of [[800,600],[600,800],[500,500]])for(const z of [1,1.5,3])for(const p of [-2,-1,0,1,2]){const r=F.cropRect(w,h,z,p,p);assert.ok(r.sx>=-1e-9&&r.sy>=-1e-9&&r.sx+r.side<=w+1e-9&&r.sy+r.side<=h+1e-9)}assert.equal(F.cropRect(800,600,1,0,0).side,600)});
t('profile/claim parsing is strict and tolerant of double-encoding',()=>{assert.equal(F.parseProfile(''),null);assert.equal(F.parseProfile('{bad'),null);const p=F.makeProfile({mid:'a1b2c3d4',name:'  Ana  ',team:'T<x>'});assert.equal(p.name,'Ana');assert.ok(!/</.test(p.team));assert.equal(F.parseProfile(JSON.stringify(JSON.stringify(p))).name,'Ana');assert.equal(F.parseClaim(JSON.stringify({mid:'zz',i:1})),null);assert.ok(F.parseClaim(JSON.stringify({mid:'a1b2c3d4',i:2,name:'x',team:'y'})))});
t('duplicate names get a (2) suffix, case-insensitively, up to many',()=>{assert.equal(F.uniqueName('Ana',[]),'Ana');assert.equal(F.uniqueName('Ana',['ana']),'Ana (2)');assert.equal(F.uniqueName('Ana',['Ana','Ana (2)']),'Ana (3)');assert.ok(F.uniqueName('x'.repeat(30),['x'.repeat(30)]).length<=30)});

/* ---------- join + slot claiming ---------- */
const mkJoin=(io,K,meta)=>(mid,name,lat)=>F.joinLeague({read:io.read,write:io.write,sleep:io.sleep,url:(i,g)=>K.slot(i,g)},{meta,mid,name,team:name+'s',sh:'',wait:1});
t('join: sequential joins fill slots 1..N in order, then the league is full',async()=>{const io=fakeStore(1),K=F.Keys('AAAAAAAAAAAAAAAA');const meta=lobbyMeta({managers:4});const j=mkJoin(io,K,meta);const got=[];for(let i=0;i<4;i++){const r=await j('a0b1c2d'+i,'M'+i);assert.ok(r.ok);got.push(r.slot)}assert.deepEqual(got,[1,2,3,4]);const r=await j('a0b1c2ff','Late');assert.equal(r.ok,false);assert.ok(r.full)});
t('join race: 12 phones join a 12-spot league at once, every slot is unique',async()=>{const io=fakeStore(3),K=F.Keys('BBBBBBBBBBBBBBBB');const meta=lobbyMeta({managers:12});const j=mkJoin(io,K,meta);const rs=await Promise.all(Array.from({length:12},(_,i)=>j('c0d0e0'+String(10+i),'P'+i)));
  const slots=rs.filter(r=>r.ok).map(r=>r.slot);assert.equal(new Set(slots).size,slots.length);assert.ok(slots.length>=1);
  /* the stored truth: each slot key holds exactly one mid, and no mid sits in two slots */
  const claims={};for(let i=1;i<=12;i++)claims[i]=F.parseClaim(io.kv[K.slot(i,0)]);const jl=F.joinedList(meta,claims);assert.equal(new Set(jl.map(c=>c.mid)).size,jl.length)});
t('join race: 8 phones, 4 spots: exactly 4 winners, 4 told "full"; nobody double-seated',async()=>{let tot=0;for(let rep=0;rep<5;rep++){const io=fakeStore(2),K=F.Keys('CCCCCCCCCCCCCC'+rep+'C');const meta=lobbyMeta({managers:4});const j=mkJoin(io,K,meta);const rs=await Promise.all(Array.from({length:8},(_,i)=>j('e0f0a0'+String(10+i),'Q'+i)));const win=rs.filter(r=>r.ok);const full=rs.filter(r=>!r.ok&&r.full);assert.ok(win.length<=4);assert.equal(new Set(win.map(r=>r.slot)).size,win.length);assert.equal(win.length+full.length,8);tot+=win.length}assert.ok(tot>=5)});
t('claimKey is idempotent for the same person (refresh/retry does not create a second claim)',async()=>{const io=fakeStore(1),K=F.Keys('DDDDDDDDDDDDDDDD');const meta=lobbyMeta({managers:4});const j=mkJoin(io,K,meta);const a=await j('a1a1a1a1','Ana');const claims={};claims[a.slot]=F.parseClaim(io.kv[K.slot(a.slot,0)]);
  const r=await F.claimKey({read:io.read,write:io.write,sleep:io.sleep},{url:K.slot(a.slot,0),mine:a.claim,parse:F.parseClaim,same:(x,y)=>x.mid===y.mid,held:x=>true,wait:1});assert.ok(r.ok)});
t('removal frees the slot: generation bump invalidates the old claim and a new person can take it',async()=>{const io=fakeStore(1),K=F.Keys('EEEEEEEEEEEEEEEE');let meta=lobbyMeta({managers:4});let j=mkJoin(io,K,meta);const a=await j('a1a1a1a1','Ana'),b=await j('b2b2b2b2','Ben');
  const rd=()=>{const c={};for(let i=1;i<=4;i++)c[i]=F.parseClaim(io.kv[K.slot(i,meta.slotGen[i]||0)]||'');return c};assert.equal(F.joinedList(meta,rd()).length,2);
  const rm=F.mRemove(meta,'a1a1a1a1',a.slot);assert.ok(rm.freed);meta=rm.state;j=mkJoin(io,K,meta);assert.deepEqual(F.joinedList(meta,rd()).map(c=>c.mid),['b2b2b2b2']);assert.deepEqual(F.freeSlots(meta,rd()),[1,3,4]);
  const c=await j('c3c3c3c3','Cy');assert.equal(c.slot,1);assert.equal(c.claim.gen,1);assert.deepEqual(F.joinedList(meta,rd()).map(x=>x.mid),['c3c3c3c3','b2b2b2b2'])});
t('managersView merges profile + commissioner overrides (rename, away)',()=>{let meta=lobbyMeta({managers:4});const claims={1:F.makeClaim({mid:'a1a1a1a1',i:1,name:'Ana',team:'Aces'}),2:null,3:null,4:null};const prof={a1a1a1a1:F.makeProfile({mid:'a1a1a1a1',name:'Ana B',team:'Aces II',emoji:'🔥'})};let v=F.managersView(meta,claims,prof);assert.equal(v[0].name,'Ana B');assert.equal(v[0].emoji,'🔥');
  meta=F.mRename(meta,'a1a1a1a1',{name:'Anna'},['Ben']).state;meta=F.mAway(meta,'a1a1a1a1',true).state;v=F.managersView(meta,claims,prof);assert.equal(v[0].name,'Anna');assert.ok(v[0].away);assert.ok(F.mRename(meta,'a1a1a1a1',{name:'  '},[]).error);assert.equal(F.mRename(meta,'b',{name:'Ben'},['ben']).state.over.b.name,'Ben (2)')});

/* ---------- live draft: replay, claims, leave/away, clock, auto-pick ---------- */
const live=(n,o)=>{let m=lobbyMeta(Object.assign({managers:n,rounds:3,type:'snake',clockSecs:60},o||{}));m.settings.orderMode='manual';return startAny(m,J(n),NOW,'s',162).state};
const ent=(m,n,tid,o)=>{const s=F.slotAt(m.order,n,m.settings.type,m.settings.rounds);return F.makeEntry(n,(o&&o.owner)||s.owner,tid,Object.assign({epoch:m.epoch,now:NOW+n*1000,writer:'t'},o))};
t('replay: valid prefix only; a duplicate team, wrong owner or hole stops it',()=>{const m=live(4);const pool=new Set(POOL);const E={1:ent(m,1,'1000'),2:ent(m,2,'1001'),3:ent(m,3,'1000'),4:ent(m,4,'1002')};let r=F.replay(m,E,pool);assert.equal(r.picks.length,2);assert.equal(r.rejected[0].why,'duplicate-team');
  E[3]=ent(m,3,'1003',{owner:'m0'});r=F.replay(m,E,pool);assert.equal(r.picks.length,2);assert.equal(r.rejected[0].why,'wrong-owner');E[3]=ent(m,3,'zzz');assert.equal(F.replay(m,E,pool).rejected[0].why,'not-in-pool');delete E[3];assert.equal(F.replay(m,E,pool).picks.length,2)});
t('replay: old-epoch and voided entries are ignored silently (undo/reset)',()=>{const m=live(4);const E={1:ent(m,1,'1000'),2:ent(m,2,'1001')};const v=F.mUndo(m,F.deriveState(m,E,{},new Set(POOL)),2,NOW).state;const r=F.replay(v,E,new Set(POOL));assert.equal(r.picks.length,1);assert.equal(r.rejected.length,0);const rs=F.mReset(m).state;assert.equal(rs.epoch,2);assert.equal(F.replay(Object.assign({},rs,{status:'live',order:m.order}),E,new Set(POOL)).picks.length,0)});
t('first-pick-wins: two phones write the same slot, one entry lands, the other is told "beaten"',async()=>{const m=live(4);const io=fakeStore(4);const url='slot';const mk=(who,tid)=>{const e=ent(m,1,tid,{writer:who});const adopted=[];return F.submitSlot({read:io.read,write:io.write,sleep:io.sleep,adopt:(n,x)=>adopted.push(x),later:()=>{},alert:()=>{}},{url,entry:e,meta:m,n:1,taken:{},pool:new Set(POOL)}).then(r=>Object.assign(r,{e}))};
  const rs=await Promise.all([mk('a','1000'),mk('b','1001')]);const w=rs.filter(r=>r.ok),l=rs.filter(r=>!r.ok);assert.equal(w.length+l.length,2);assert.ok(w.length>=1);const final=F.parseEntry(io.kv[url]);assert.ok(w.every(r=>r.e.id===final.id));if(l.length)assert.ok(l[0].beaten)});
t('first-pick-wins: a late writer sees the existing valid pick and does not overwrite',async()=>{const m=live(4);const io=fakeStore(1);const first=ent(m,1,'1000');io.kv.slot=JSON.stringify(first);const r=await F.submitSlot({read:io.read,write:io.write,sleep:io.sleep,adopt:()=>{},later:()=>{},alert:()=>{}},{url:'slot',entry:ent(m,1,'1001'),meta:m,n:1,taken:{},pool:new Set(POOL)});assert.ok(r.beaten);assert.equal(F.parseEntry(io.kv.slot).id,first.id);assert.equal(io.writes,0)});
t('a slot holding an invalid/voided entry can be overwritten (undo then re-pick)',()=>{const m=live(4);const e1=ent(m,1,'1000');const m2=Object.assign({},m,{voided:[e1.id]});assert.ok(F.slotWritable(m2,e1,1,{},new Set(POOL)));assert.ok(!F.slotWritable(m,e1,1,{},new Set(POOL)));assert.ok(F.slotWritable(m,null,1,{}))});
t('validatePick: turn, taken, pool, paused, not live',()=>{const m=live(3);const st=F.deriveState(m,{},{},new Set(POOL));assert.ok(F.validatePick(st,'m0','1000',{pool:new Set(POOL)}).ok);assert.ok(F.validatePick(st,'m1','1000').turn);assert.ok(F.validatePick(st,'m0','nope',{pool:new Set(POOL)}).error);const st2=F.deriveState(m,{1:ent(m,1,'1000')},{},new Set(POOL));assert.ok(F.validatePick(st2,'m1','1000').taken);assert.ok(F.validatePick(Object.assign({},st,{paused:true}),'m0','1000').error);assert.ok(F.validatePick(Object.assign({},st,{status:'lobby'}),'m0','1000').error)});
t('draft completes after N×R picks and then locks (undo refused, pick refused)',()=>{const m=live(4,{rounds:2});const E={};for(let n=1;n<=8;n++)E[n]=ent(m,n,String(1000+n));const st=F.deriveState(m,E,{},new Set(POOL));assert.equal(st.status,'complete');assert.equal(st.total,8);assert.equal(F.onClock(st),null);assert.ok(F.mUndo(Object.assign({},m,{status:'complete'}),st,8,NOW).error);assert.ok(F.validatePick(st,'m0','1100').error);assert.equal(st.deadline,null)});
t('every manager ends with exactly `rounds` teams, no team twice, in a full 8-manager 8-round snake',()=>{const m=live(8,{rounds:8});const E={};F.pickSeq(m.order,8,'snake').forEach(s=>{E[s.n]=ent(m,s.n,String(1000+s.n))});const st=F.deriveState(m,E,{},new Set(POOL));assert.equal(st.picks.length,64);assert.equal(new Set(st.picks.map(p=>p.tid)).size,64);m.order.forEach(o=>assert.equal(F.ownerCount(st,o),8));assert.equal(st.status,'complete')});
t('clock: deadline = last pick time + clock; none when paused or no clock; resume keeps the time left',()=>{const m=live(4);let st=F.deriveState(m,{},{},new Set(POOL));assert.equal(st.deadline,NOW+60e3);const E={1:ent(m,1,'1000')};st=F.deriveState(m,E,{},new Set(POOL));assert.equal(st.deadline,NOW+1000+60e3);
  const p=F.mPause(m,st,true,NOW+21e3).state;assert.equal(p.pausedLeft,40e3);assert.equal(F.deriveState(p,E,{},new Set(POOL)).deadline,null);const r=F.mResume?0:F.mPause(p,st,false,NOW+100e3).state;const st3=F.deriveState(r,E,{},new Set(POOL));assert.equal(st3.deadline,NOW+100e3+40e3);
  assert.equal(F.deriveState(F.mClock(m,0,NOW).state,{},{},new Set(POOL)).deadline,null);assert.ok(F.mClock(m,45,NOW).error);assert.equal(F.mClock(m,30,NOW).state.settings.clockSecs,30)});
t('pause: double pause and resume-when-not-paused are refused; undo while paused re-arms a full clock',()=>{const m=live(4);const st=F.deriveState(m,{1:ent(m,1,'1000')},{},new Set(POOL));const p=F.mPause(m,st,true,NOW+5e3).state;assert.ok(F.mPause(p,st,true,NOW).error);assert.ok(F.mPause(m,st,false,NOW).error);const u=F.mUndo(p,st,1,NOW+9e3).state;assert.equal(u.pausedLeft,60e3)});
t('undo: only the latest pick, and only if the board did not move',()=>{const m=live(4);const E={1:ent(m,1,'1000'),2:ent(m,2,'1001')};const st=F.deriveState(m,E,{},new Set(POOL));assert.ok(F.mUndo(m,st,1,NOW).error);assert.ok(F.mUndo(m,st,null,NOW).error,'no expectation means no undo');assert.ok(F.mUndo(m,st,{n:2,id:'someone-elses-pick'},NOW).error,'right number, wrong pick id');const u=F.mUndo(m,st,{n:2,id:st.picks[1].id},NOW);assert.equal(u.undone.n,2);assert.ok(F.mUndo(m,F.deriveState(m,{},{},new Set(POOL)),null,NOW).error)});
t('CAS: a stale-chain orphan does not replay after undo and re-pick; a stale undo cannot remove or restore picks',()=>{const m=live(4);const e1=ent(m,1,'1000',{prev:''}),e2=ent(m,2,'1001',{prev:e1.id}),e3=ent(m,3,'1002',{prev:e2.id});let E={1:e1,2:e2,3:e3};let st=F.deriveState(m,E,{},new Set(POOL));assert.equal(st.picks.length,3);
  /* commissioner A looked when 2 picks existed; pick 3 landed; the stale undo must fail */ const stale={n:2,id:e2.id};assert.ok(F.mUndo(m,st,stale,NOW).error);
  const u=F.mUndo(m,st,{n:3,id:e3.id},NOW);const m2=u.state;const st2=F.deriveState(m2,E,{},new Set(POOL));assert.equal(st2.picks.length,2);
  /* a second, stale undo of the same pick is refused */ assert.ok(F.mUndo(m2,st2,{n:3,id:e3.id},NOW).error);
  /* slot 3 is re-picked with a different team: fine; then a late orphan for slot 4 chained to the OLD pick 3 must not replay */ const e3b=ent(m2,3,'1005',{prev:e2.id,id:'new3'});E={1:e1,2:e2,3:e3b,4:ent(m2,4,'1003',{prev:e3.id,id:'orph4'})};const st3=F.deriveState(m2,E,{},new Set(POOL));assert.deepEqual(st3.picks.map(p=>p.id),[e1.id,e2.id,'new3']);
  /* an entry chained to the right predecessor is accepted */ E[4]=ent(m2,4,'1003',{prev:'new3',id:'ok4'});assert.equal(F.deriveState(m2,E,{},new Set(POOL)).picks.length,4);
  /* the slot with a stale orphan may be overwritten, a valid one may not */ assert.ok(F.slotWritable(m2,ent(m2,4,'1003',{prev:e3.id,id:'orph4'}),4,{},new Set(POOL),'new3'));assert.ok(!F.slotWritable(m2,E[4],4,{},new Set(POOL),'new3'))});
t('undo refused when the derived state is complete even if meta still says live',()=>{const m=live(2,{rounds:1});let E={};let prev='';for(let n=1;n<=2;n++){E[n]=ent(m,n,String(1000+n),{prev});prev=E[n].id}const st=F.deriveState(m,E,{},new Set(POOL));assert.equal(st.status,'complete');assert.equal(m.status,'live');assert.ok(F.mUndo(m,st,{n:2,id:E[2].id},NOW).error)});
t('autoReason: timeout (clock out + league auto-pick on), away, manager auto, grace period, legacy autoPick:false still auto-picks (k), no clock',()=>{const m=live(4);let st=F.deriveState(m,{},{},new Set(POOL));assert.equal(F.autoReason(st,NOW+59e3,0),null);assert.equal(F.autoReason(st,NOW+60e3+1,0),'expired');assert.equal(F.autoReason(st,NOW+61e3,2000),null);assert.equal(F.autoReason(st,NOW+63e3,2000),'expired');
  const offm=F.mFlags(m,{autoPick:false}).state;const off=F.deriveState(offm,{},{},new Set(POOL));assert.equal(F.autoReason(off,NOW+999e3,0),'expired')/* s25-full (k, Paul): an older autoPick:false league auto-picks at clock-out too */;assert.equal(offm.settings.autoPick,false)/* the stored setting is left as is */;const nc=F.deriveState(F.mClock(m,0,NOW).state,{},{},new Set(POOL));assert.equal(F.autoReason(nc,NOW+999e3,0),null);
  const aw=F.deriveState(F.mAway(m,'m0',true).state,{},{},new Set(POOL));assert.equal(F.autoReason(aw,NOW,0),'away');const au=F.deriveState(m,{},{m0:{auto:true,queue:[]}},new Set(POOL));assert.equal(F.autoReason(au,NOW,0),'auto');const pz=F.deriveState(F.mFlags(m,{}).state,{},{},new Set(POOL));pz.paused=true;assert.equal(F.autoReason(pz,NOW+999e3,0),null)});
t('autoChoice: queue first (skipping taken), then best power rank, then seeded random',()=>{const m=live(4);const E={1:ent(m,1,'1000')};const st=F.deriveState(m,E,{m1:{queue:['1000','1005','1006']}},new Set(POOL));
  assert.deepEqual(F.autoChoice(st,'m1',POOL,null,()=>0),{tid:'1005',from:'queue'});const st2=F.deriveState(m,E,{},new Set(POOL));const rank=t=>t==='1000'?1:t==='1010'?2:t==='1003'?3:0;assert.deepEqual(F.autoChoice(st2,'m1',POOL,null,rank),{tid:'1010',from:'power'});
  const a=F.autoChoice(st2,'m1',POOL,F.mulberry(5),()=>0),b=F.autoChoice(st2,'m1',POOL,F.mulberry(5),()=>0);assert.deepEqual(a,b);assert.equal(a.from,'random');assert.notEqual(a.tid,'1000');assert.equal(F.autoChoice(st2,'m1',[],null,()=>0),null)});
t('auto-pick entries are deterministic ids so two phones auto-picking write the same pick',()=>{const m=live(4);const a=F.makeEntry(1,'m0','1000',{by:'auto',epoch:1,now:1,writer:'x'}),b=F.makeEntry(1,'m0','1000',{by:'auto',epoch:1,now:2,writer:'y'});assert.equal(a.id,b.id);const mine=F.makeEntry(1,'m0','1000',{epoch:1});assert.notEqual(mine.id,a.id)});
t('leave/away: marking away flags them; removing mid-draft keeps their seat and auto-picks; their order spot is not lost',()=>{const m=live(4);let r=F.mRemove(m,'m2',3);assert.equal(r.freed,false);assert.ok(r.state.over.m2.left&&r.state.over.m2.away);assert.deepEqual(r.state.order,m.order);const st=F.deriveState(r.state,{1:ent(m,1,'1000'),2:ent(m,2,'1001')},{},new Set(POOL));assert.equal(st.away.m2,true);assert.equal(F.autoReason(st,NOW,0),'away');
  const back=F.mAway(r.state,'m2',false).state;assert.ok(!back.over.m2.away)});
t('leave in the lobby frees the slot and the order forgets them',()=>{let m=F.mSetOrder(lobbyMeta(),J(4),['m3','m2','m1','m0']).state;const r=F.mRemove(m,'m2',3);assert.ok(r.freed);assert.deepEqual(r.state.order,['m3','m1','m0']);assert.equal(r.state.slotGen[3],1);assert.ok(F.mRemove(Object.assign({},m,{status:'complete'}),'m2',3).error)});
t('late joiner: after the draft started the order is fixed, so a new person is not in it (spectator)',()=>{const m=live(4);const ord=F.effectiveOrder(m,[...J(4),'late1']);assert.deepEqual(startAny(lobbyMeta(),J(4),NOW,'s',162).state.order.length,4);assert.ok(F.pickSeq(m.order,3,'snake').every(s=>s.owner!=='late1'));assert.ok(ord.includes('late1'));/* effectiveOrder alone would add them, but the room only uses it in the lobby */assert.deepEqual(m.order,J(4))});
t('end early: only a live draft; locks it; partial recap data stays',()=>{const m=live(4);assert.ok(F.mEnd(lobbyMeta(),NOW).error);const e=F.mEnd(m,NOW).state;assert.equal(e.status,'complete');assert.ok(e.endedEarly);const st=F.deriveState(e,{1:ent(m,1,'1000')},{},new Set(POOL));assert.equal(st.status,'complete');assert.equal(st.picks.length,1);assert.ok(st.endedEarly);assert.ok(F.mReset(e).error);assert.ok(F.mEnd(e,NOW).error)});
t('reset: new epoch, back to lobby, managers/slots/pass kept',()=>{const m=Object.assign(live(4),{pass:{salt:'a',hash:'b'}});m.slotGen={2:1};m.over={m1:{away:true,left:true}};const r=F.mReset(m).state;assert.equal(r.status,'lobby');assert.equal(r.epoch,m.epoch+1);assert.deepEqual(r.pass,m.pass);assert.deepEqual(r.slotGen,{2:1});assert.ok(r.over.m1.away&&!r.over.m1.left);assert.deepEqual(r.order,[])});
t('meta normalisation survives garbage',()=>{for(const g of [null,'x',[],{},{status:'weird',order:'no',settings:{clockSecs:7}}]){const m=F.normalizeMeta(g);assert.ok(['lobby','live','complete'].includes(m.status));assert.ok(Array.isArray(m.order));assert.equal(m.settings.clockSecs,60)}assert.ok(!F.exists({}));assert.ok(F.exists(F.defaultMeta('X',base(),'m')))});

/* ---------- passcode (friendly lock) ---------- */
t('commissioner secret: random, salted SHA-256; a copied hash unlocks nothing; secret never stored',async()=>{const sec=F.newSecret();assert.match(sec,/^[0-9a-f]{32}$/);assert.notEqual(sec,F.newSecret());const a=await F.makePass(sec);const b=await F.makePass(sec);assert.notEqual(a.hash,b.hash);assert.equal(a.hash.length,64);assert.equal(await F.sha256Hex('abc'),'ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad');
  const m=Object.assign(lobbyMeta(),{pass:a});assert.ok(await F.checkPass(m,sec));assert.ok(!await F.checkPass(m,F.newSecret()));assert.ok(!await F.checkPass(lobbyMeta(),sec));
  assert.ok(!await F.checkPass(m,a.hash),'the public hash must not work as the token');assert.ok(!await F.checkPass(m,a.salt+':'+sec));assert.ok(!await F.checkPass(m,''));assert.ok(!JSON.stringify(m).includes(sec))});
t('manager secret: only the claim holder secret verifies; hash and other managers secret fail; no hash means no access',async()=>{const k1=F.newSecret(),k2=F.newSecret();const c1={mid:'aaaaaaaaaaaa',sh:await F.mgrHash('aaaaaaaaaaaa',k1)};
  assert.ok(await F.checkMgrSecret(c1,k1));assert.ok(!await F.checkMgrSecret(c1,k2));assert.ok(!await F.checkMgrSecret(c1,c1.sh));assert.ok(!await F.checkMgrSecret(c1,''));assert.ok(!await F.checkMgrSecret({mid:'aaaaaaaaaaaa'},k1));assert.ok(!await F.checkMgrSecret(null,k1));
  assert.ok(!await F.checkMgrSecret({mid:'bbbbbbbbbbbb',sh:c1.sh},k1),'the hash is bound to the manager id');assert.ok(!await F.checkMgrSecret({mid:'aaaaaaaaaaaa',sh:await F.sha256Hex(k1)},k1),'unsalted legacy form is not accepted')});
t('links: fragment secrets are extracted from links or bare codes; junk is rejected',()=>{const k=F.newSecret();assert.equal(F.extractSecret('https://x.test/room.html?l=abc#cm='+k,'cm'),k);assert.equal(F.extractSecret(k.toUpperCase(),'cm'),k);assert.equal(F.extractSecret('cm=zz','cm'),'');assert.equal(F.extractSecret('<script>','cm'),'');
  const x=F.extractMgr('https://x.test/room.html?l=abc#as=0123456789ab&k='+k);assert.deepEqual(x,{mid:'0123456789ab',k});assert.equal(F.extractMgr('https://x.test/room.html?l=abc#as=0123456789ab'),null);assert.equal(F.extractMgr('#as="><img&k='+k),null)});
t('chat sanitiser: unsafe ids and reaction keys are dropped, text is capped, shape is forced',()=>{const k=F.normChat({msgs:[{id:'a"><img src=x onerror=alert(1)>',who:'m1',text:'hi',ts:1},{id:'ok_1',who:'m1',text:'x'.repeat(900),ts:2,r:{'👍':['m1'],'"><script>':['m2'],'😂':'zzz'}},{id:'ok2',who:{x:1},text:5}],version:3});
  assert.ok(!k.msgs.some(m=>/[<>"]/.test(m.id)));const m=k.msgs.find(m=>m.id==='ok_1');assert.ok(m&&m.text.length<=280);assert.ok(!k.msgs.some(m=>m.id==='ok2'));assert.ok(Object.keys(m.r||{}).every(e=>F.REACTS.includes(e)));assert.ok(!JSON.stringify(k).includes('<script>'));assert.deepEqual(F.normChat('junk').msgs,[]);assert.deepEqual(F.normChat(null).msgs,[]);assert.ok(F.safeId('abc-1_2')&&!F.safeId('a b')&&!F.safeId('a"b')&&!F.safeId(5)&&!F.safeId(''))});

