t('spin: a full spin yields a permutation; invalid records are rejected; apply sets the order',()=>{let m=F.mSpinStart(lobbyMeta(),J(5)).state;const winners=[];for(let i=0;i<5;i++){const s=F.makeSpin(m,winners,NOW);assert.ok(F.spinValid(m,winners,s));winners.push(s.winner)}assert.ok(F.permutationOf(winners,J(5)));
  const bad=F.makeSpin(m,[],NOW);bad.winner='zz';assert.ok(!F.spinValid(m,[],bad));const rp=F.spinReplay(m,Object.fromEntries(winners.map((w,i)=>[i+1,{id:'x',gen:1,n:i+1,idx:F.remainingPlayers(J(5),winners.slice(0,i)).indexOf(w),winner:w}])));assert.ok(rp.done);const a=F.mSpinApply(m,winners,J(5),NOW);assert.deepEqual(a.state.order,winners);assert.ok(a.state.orderSet&&a.state.spin.done);assert.ok(F.mSpinApply(m,winners.slice(1),J(5),NOW).error);assert.ok(F.mSpinApply(m,winners,[...J(5),'x'],NOW).error)});
