/* s26c6s: s26c added the STOOPIDS 2026-27 recap import (recap.html?import=stoopids-2026-27, import/stoopids-draft-results.json, League site fallback link); those exact references are allowed (and s26c7's js/scoring.js comments naming the STOOPIDS 'win' / conf_reg rules), any other live-pool mention still fails */
const IMPORT_OK=/stoopids[- ]2026-27|import\/stoopids-draft-results\.json|https:\/\/stoopids\.github\.io\/stoopids\/|confirmed by Stoopids Site/gi;
t('no gambling/money language in shipped source or pages',()=>{const fs=require('fs'),path=require('path');const root=path.join(__dirname,'..');const files=['index.html','help.html','setup.html','join.html','room.html','recap.html','league.html','time.html',...fs.readdirSync(root+'/js').filter(f=>f.endsWith('.js')&&f!=='qr.min.js').map(f=>'js/'+f),'css/app.css'];
  /* s20: the League site has a Bets tab (pushup challenges). The words bet/bets/betting, owes/owed, odds and stake(s) are allowed ONLY in the Bets files (js/league-bets.js)
     and the files that name or link the tab (js/leaguehome.js, league.html, help.html). Money, currency, prize, payout, jackpot, lottery, gamble, wager, cash and $ amounts are forbidden in EVERY file, Bets files included. */
  const BETS_OK=['js/league-bets.js','js/leaguehome.js','league.html','help.html'];
  const bad0=/\b(bets?|betting|stakes?|iou|owes?|owed|odds)\b/i,bad1=/\b(wager\w*|entry fee|prize|payout|jackpot|lottery|gambl\w*|buy-?in|pot|cash|money|dollars?)\b|\$\s?\d/i,bad2=/\b(USD|IDR)\b|\bRp\s?\d/;
  const files2=files.slice();fs.readdirSync(root+'/css').filter(f=>/\.css$/.test(f)).forEach(f=>files2.push('css/'+f));
  files2.forEach(f=>{const s0=fs.readFileSync(path.join(root,f),'utf8').replace(/espn\.com[^\s"']*/g,'').replace(f==='js/core.js'?/\$\d/g:/^$/g,'');const m1=bad1.exec(s0)||bad2.exec(s0);assert.ok(!m1,f+' contains "'+(m1&&m1[0])+'" near: '+(m1&&s0.slice(Math.max(0,m1.index-30),m1.index+30)))});
  const bad={exec:s=>BETS_OK.includes(CUR)?null:bad0.exec(s)};let CUR='';files.forEach(f=>{CUR=f;const s=fs.readFileSync(path.join(root,f),'utf8').replace(/espn\.com[^\s"']*/g,'');const m=bad.exec(s);assert.ok(!m,f+' contains "'+(m&&m[0])+'" near: '+(m&&s.slice(Math.max(0,m.index-30),m.index+30)));assert.ok(!/stoopid/i.test(f==='js/recap.js'?s.replace(IMPORT_OK,''):f==='js/scoring.js'?s.replace(/STOOPIDS (?:'win'|conf_reg)/g,''):s),f+' mentions the live pool')})});
