 for(const w of ['Create','Invite link','private commissioner link','Join','order','Start draft','Pause','Undo','Mark away','Auto-pick','private manager link','Spectator','League site','Recap','Known limits','page must be open'])assert.ok(new RegExp(w,'i').test(txt),'missing: '+w);
