  const nextN=s4.picks.length+1;put(nextN,MIDS[0],'1102',s4.picks[s4.picks.length-1].id);const s5=F.deriveState(m2,ent,{},new Set(POOL));assert.equal(s5.status,'complete','the draft ends after the last real pick');assert.equal(s5.real.length,3);assert.equal(s5.picks.length,16);
