t('s25b zone labels come from Intl (viewer device zone); US DST change Nov 1 2026 handled; no hard-coded ET in Draft Room files',()=>{const la='America/Los_Angeles';
 assert.equal(F.parseLocalInput('2026-11-01T20:00',la),Date.UTC(2026,10,2,4,0));assert.equal(F.parseLocalInput('2026-10-31T20:00',la),Date.UTC(2026,10,1,3,0));
 assert.equal(F.zoneAbbr(Date.UTC(2026,10,2,4,0),la),'PST');assert.equal(F.zoneAbbr(Date.UTC(2026,10,1,3,0),la),'PDT');assert.equal(F.zoneAbbr(0,'Asia/Jakarta'),'GMT+7');
 assert.equal(F.fmtLong(Date.UTC(2026,10,2,4,0),la),'Sunday, November 1, 2026 at 8:00 PM PST');
 const fs=require('fs'),path=require('path');const root=path.join(__dirname,'..');const OWN=['index.html','setup.html','join.html','room.html','recap.html','time.html','redraft.html','mock.html',...['core','store','ui','setup','join','room','recap','index','time','redraft','mock','links-card','scoring','help'].map(n=>'js/'+n+'.js')];
 OWN.forEach(f=>{const p=path.join(root,f);if(!fs.existsSync(p))return;const t=fs.readFileSync(p,'utf8');assert.ok(!/America\/New_York|\bET\b/.test(t.replace(/\/\*[\s\S]*?\*\//g,'')),f+' has a hard-coded ET zone')})});
t('s25-full F.consumeUrlSecret: League call shape (one name -> string) and bare route hashes (#bets) survive',()=>{
 const mk=(href)=>{const u=new URL(href);const w={location:{pathname:u.pathname,search:u.search,hash:u.hash},history:{state:null,replaceState:(s,t,p)=>{w.to=p}}};return w};
 let w=mk('https://x/league.html?l=AB#bets&as=abc123&k=k1');assert.equal(F.consumeUrlSecret('as',w),'abc123');assert.equal(w.to,'/league.html?l=AB#bets&k=k1');
 w=mk('https://x/league.html?l=AB#bets&as=a&k=k1&cm=c');const o=F.consumeUrlSecret(['as','k','cm'],w);assert.deepEqual(o,{as:'a',k:'k1',cm:'c'});assert.equal(w.to,'/league.html?l=AB#bets');
 w=mk('https://x/room.html?l=AB&k=q#tab=chat&k=h');assert.equal(F.consumeUrlSecret('k',w),'h');assert.equal(w.to,'/room.html?l=AB#tab=chat');
 w=mk('https://x/room.html?l=AB#tab=board');assert.equal(F.consumeUrlSecret('k',w),'');assert.equal(w.to,undefined)});

t('s25-full F.consumeUrlSecret: reads k / as / cm from the hash and the query, strips them with replaceState, keeps every other param',()=>{const calls=[];
 const win=u=>{const x=new URL(u);return{location:{pathname:x.pathname,search:x.search,hash:x.hash},history:{replaceState:(a,b,c)=>calls.push(c)}}};
 let r=F.consumeUrlSecret(['cm','as','k'],win('https://h/room.html?l=ABC#as=m1&k=s3cret&tab=teams'));assert.deepEqual(r,{as:'m1',k:'s3cret'});assert.equal(calls.pop(),'/room.html?l=ABC#tab=teams');
 r=F.consumeUrlSecret(['cm','as','k'],win('https://h/room.html?l=ABC&as=m1&k=old&x=1'));assert.equal(r.k,'old');assert.equal(calls.pop(),'/room.html?l=ABC&x=1');
 r=F.consumeUrlSecret(['cm'],win('https://h/room.html?l=ABC#cm=WRONG'));assert.equal(r.cm,'WRONG');assert.equal(calls.pop(),'/room.html?l=ABC');
 const n0=calls.length;r=F.consumeUrlSecret(['k'],win('https://h/room.html?l=ABC#tab=board'));assert.deepEqual(r,{});assert.equal(calls.length,n0,'no secret: the URL is left alone')});
